style.css:
@-moz-document domain("drive.google.com") {
/* === GLOBAL DARK BACKGROUND === */
body, html {
    background: #0a0a0f !important;
    color: #00ffff !important;
    font-family: 'Segoe UI', -apple-system, system-ui, sans-serif !important;
}

/* === MAIN CONTAINER === */
.gb_df, .gb_eg, .gb_bg {
    background: linear-gradient(135deg, #0a0a0f 0%, #1a1a2e 50%, #16213e 100%) !important;
    border: 1px solid #00ffff33 !important;
}

/* === NAVIGATION HEADER === */
.gb_jd, .gb_kd, .gb_md {
    background: rgba(10, 10, 15, 0.95) !important;
    border-bottom: 2px solid #00ffff !important;
    backdrop-filter: blur(10px) !important;
}

/* === SIDEBAR === */
.h-sb-Al, .a-Zb-Zb, .a-s-fa-Ha-pa {
    background: linear-gradient(180deg, #0f0f1f 0%, #1a1a2e 100%) !important;
    border-right: 1px solid #00ffff55 !important;
}

/* === SIDEBAR ITEMS === */
.a-s-fa-Ha-pa .h-sb-kc, .a-s-fa-Ha-pa .h-sb-wc {
    color: #00ffff !important;
    transition: all 0.3s ease !important;
}

.a-s-fa-Ha-pa .h-sb-kc:hover, .a-s-fa-Ha-pa .h-sb-wc:hover {
    background: rgba(0, 255, 255, 0.1) !important;
    color: #ffffff !important;
    border-radius: 8px !important;
    box-shadow: 0 0 10px rgba(0, 255, 255, 0.3) !important;
}

/* === MAIN CONTENT AREA === */
.a-pb-T-Jw, .a-t-j, .a-t-j-T {
    background: linear-gradient(145deg, #0a0a0f 0%, #1a1a2e 100%) !important;
    color: #00ffff !important;
}

/* === FILE GRID === */
.a-u-B-Oc-f, .a-u-B-Oc-f-Fb {
    background: rgba(26, 26, 46, 0.8) !important;
    border: 1px solid #00ffff33 !important;
    border-radius: 12px !important;
    transition: all 0.3s ease !important;
}

.a-u-B-Oc-f:hover {
    background: rgba(0, 255, 255, 0.1) !important;
    border: 1px solid #00ffff !important;
    box-shadow: 0 5px 20px rgba(0, 255, 255, 0.2) !important;
    transform: translateY(-2px) !important;
}

/* === FILE NAMES === */
.a-u-B-Oc-oa-k, .a-u-B-Oc-oa-k-f {
    color: #ffffff !important;
    font-weight: 500 !important;
}

/* === BUTTONS === */
.a-s-fa-Ha-pa-f-jb, button, .gb_Ra {
    background: linear-gradient(135deg, #00ffff22 0%, #0066ff22 100%) !important;
    border: 1px solid #00ffff !important;
    color: #00ffff !important;
    border-radius: 8px !important;
    transition: all 0.3s ease !important;
}

.a-s-fa-Ha-pa-f-jb:hover, button:hover, .gb_Ra:hover {
    background: linear-gradient(135deg, #00ffff44 0%, #0066ff44 100%) !important;
    color: #ffffff !important;
    box-shadow: 0 0 15px rgba(0, 255, 255, 0.4) !important;
    transform: scale(1.05) !important;
}

/* === CREATE BUTTON === */
.a-s-tb-r-Jw-atb, .gb_te {
    background: linear-gradient(135deg, #ff0080 0%, #ff4000 100%) !important;
    color: #ffffff !important;
    border: none !important;
    border-radius: 25px !important;
    box-shadow: 0 4px 15px rgba(255, 0, 128, 0.3) !important;
}

.a-s-tb-r-Jw-atb:hover {
    box-shadow: 0 6px 25px rgba(255, 0, 128, 0.5) !important;
    transform: translateY(-2px) scale(1.05) !important;
}

/* === SEARCH BAR === */
.gb_Qe, .gb_Pe, input[type="text"] {
    background: rgba(26, 26, 46, 0.9) !important;
    border: 1px solid #00ffff55 !important;
    color: #00ffff !important;
    border-radius: 20px !important;
    backdrop-filter: blur(10px) !important;
}

.gb_Qe:focus, .gb_Pe:focus, input[type="text"]:focus {
    border: 2px solid #00ffff !important;
    box-shadow: 0 0 10px rgba(0, 255, 255, 0.3) !important;
    outline: none !important;
}

/* === DROPDOWN MENUS === */
.gb_ma, .gb_Ba, .a-s-Wg-rd {
    background: linear-gradient(135deg, #0f0f1f 0%, #1a1a2e 100%) !important;
    border: 1px solid #00ffff55 !important;
    border-radius: 12px !important;
    box-shadow: 0 10px 30px rgba(0, 255, 255, 0.2) !important;
}

/* === MENU ITEMS === */
.gb_ya, .gb_za, .a-s-Wg-rd-c {
    color: #00ffff !important;
    transition: all 0.2s ease !important;
}

.gb_ya:hover, .gb_za:hover, .a-s-Wg-rd-c:hover {
    background: rgba(0, 255, 255, 0.1) !important;
    color: #ffffff !important;
}

/* === ICONS === */
.gb_yc, .gb_8c, svg, .a-s-fa-Ha-pa-f-jb-Qa {
    filter: brightness(0) invert(1) sepia(1) saturate(5) hue-rotate(180deg) !important;
}

/* === LOADING SPINNERS === */
.gb_tg {
    border-color: #00ffff transparent #00ffff transparent !important;
}

/* === SCROLLBARS === */
::-webkit-scrollbar {
    width: 8px !important;
    background: rgba(26, 26, 46, 0.5) !important;
}

::-webkit-scrollbar-thumb {
    background: linear-gradient(180deg, #00ffff 0%, #0066ff 100%) !important;
    border-radius: 4px !important;
}

::-webkit-scrollbar-thumb:hover {
    background: linear-gradient(180deg, #00ffff 0%, #ff0080 100%) !important;
}

/* === BREADCRUMBS === */
.a-pb-T-Jw-atb-ca, .a-pb-T-Jw-atb-ca-T {
    color: #00ffff !important;
}

/* === STATUS BAR === */
.a-t-j-Pa, .a-t-j-Pa-T {
    background: rgba(10, 10, 15, 0.95) !important;
    border-top: 1px solid #00ffff33 !important;
    color: #00ffff !important;
}

/* === MODAL DIALOGS === */
.a-Ud-Jb, .gb_g {
    background: linear-gradient(135deg, #0f0f1f 0%, #1a1a2e 100%) !important;
    border: 2px solid #00ffff !important;
    border-radius: 15px !important;
    box-shadow: 0 20px 50px rgba(0, 255, 255, 0.3) !important;
}

/* === PROGRESS BARS === */
.a-s-tb-r-Jw-atb-progress {
    background: linear-gradient(90deg, #00ffff 0%, #ff0080 100%) !important;
    border-radius: 10px !important;
}

/* === SELECTION HIGHLIGHT === */
::selection {
    background: rgba(0, 255, 255, 0.3) !important;
    color: #ffffff !important;
}

/* === GLOW EFFECTS === */
.a-u-B-Oc-f:hover::before {
    content: "" !important;
    position: absolute !important;
    top: 0 !important;
    left: 0 !important;
    right: 0 !important;
    bottom: 0 !important;
    background: radial-gradient(circle at center, rgba(0, 255, 255, 0.1) 0%, transparent 70%) !important;
    border-radius: 12px !important;
    pointer-events: none !important;
}

/* === ANIMATED BORDERS === */
@keyframes neonPulse {
    0%, 100% { border-color: #00ffff; box-shadow: 0 0 5px rgba(0, 255, 255, 0.3); }
    50% { border-color: #ff0080; box-shadow: 0 0 20px rgba(255, 0, 128, 0.5); }
}

.a-s-tb-r-Jw-atb {
    animation: neonPulse 2s ease-in-out infinite !important;
}
}
